const prices = $json.chart.result[0].indicators.quote[0].close;

// helper
function avg(arr) {
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

// moving averages
const last5 = prices.slice(-5);
const last20 = prices.slice(-20);

const shortMA = avg(last5);
const longMA = avg(last20);

// momentum
const momentum = shortMA - longMA;

// price change
const latest = prices[prices.length - 1];
const old = prices[prices.length - 6];

const priceChange = ((latest - old) / old) * 100;

// volatility
const mean = avg(prices);
const variance = avg(prices.map(p => (p - mean) ** 2));
const volatility = Math.sqrt(variance);

return [{
  trend: shortMA > longMA ? "uptrend" : "downtrend",
  shortMA,
  longMA,
  momentum,
  volatility,
  priceChange
}];

