return items.map(item => {
  const parsed = item.json.parsed || {};

  // Extract values
  const signal = parsed.signal;
  const strength = parsed.strength;
  const confidence = Number(parsed.confidence);
  const reason = parsed.reason;
  const risk_level = parsed.risk_level;

  // Calculate score
  const score =
    (confidence > 80 ? 50 : 0) +
    (strength === "Strong" ? 30 : 0) +
    (risk_level === "Low" ? 20 : 0);

  return {
    json: {
      signal,
      strength,
      confidence,
      reason,
      risk_level,
      score
    }
  };
});
